import pandas as pd, io
from pymatgen.core import Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
tr=pd.read_csv('nlo_shg_eg_train.csv'); po=pd.read_csv('nlo_pool.csv')
def sg(p):
 s=Structure.from_str(p,fmt='poscar'); a=SpacegroupAnalyzer(s,symprec=.01); return a.get_space_group_symbol(), a.get_space_group_number(), len(s), s.volume/len(s)
for name,df in [('TRAIN',tr),('POOL',po)]:
 print('\n',name)
 if name=='TRAIN': q=df[(df.formula.str.contains('Zn')) & (df.formula.str.contains('S')) | df.formula.str.match(r'^(Al|Ga).* S')]
 else: q=df[df.candidate_id.isin(['c024','c025','c026','c027','c028','c029','c037','c040','c041','c042','c043','c044','c045','c046','c050','c051','c052','c057','c067','c076','c077','c078','c081','c083','c086','c088','c100'])]
 for _,r in q.iterrows():
  x=sg(r.poscar)
  if name=='TRAIN': print(f'{r.formula:22s} {x[0]:10s} #{x[1]:3d} n={x[2]:2d} vpa={x[3]:6.2f} gap={r.band_gap:.3f} shg={r.shg:.2f}')
  else: print(f'{r.candidate_id} {r.formula:18s} {x[0]:10s} #{x[1]:3d} n={x[2]:2d} vpa={x[3]:6.2f}')
